    deallocate(p, data, max_size, b);
    return true;
}
if (!b) {
    b = allocate(p, data, max_size, alignment, n);
    return b.operator bool();
}
const size_t aligned_new = (n + alignment - 1) & ~(alignment - 1);
const size_t aligned_old = b.length;

if (aligned_new == aligned_old) {
    return true;
}

if (is_last_used_block(data, p, b)) {
    if (static_cast<const char*>(b.ptr) + aligned_new <= data + max_size) {
        b.length = aligned_new;
        p = static_cast<char*>(b.ptr) + aligned_new;
        return true;
    }
    return false;
}

if (aligned_new < aligned_old) {
    b.length = aligned_new;
    return true;
}

block new_block = allocate(p, data, max_size, alignment, aligned_new);
if (!new_block) {
    return false;
}

std::memcpy(new_block.ptr, b.ptr, std::min(b.length, aligned_new));
b = new_block;
return true;

